// Matches hex colors: #RRGGBB or #RRGGBBAA
export const HEX_RE = /^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})?$/i;

// Matches rgb() and rgba() formats
export const RGB_RE = /^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*(,\s*[\d.]+\s*)?\)$/i;

// Matches hsl() and hsla() formats
export const HSL_RE = /^hsla?\(\s*(\d+)\s*,\s*(\d+)%\s*,\s*(\d+)%\s*(,\s*[\d.]+\s*)?\)$/i;

